import pandas as pd
import matplotlib.pyplot as plt
import sys

def plot_idle_log(csv_path):
    # Load the telemetry CSV generated by idle_logger.py
    df = pd.read_csv(csv_path)
    df['time'] = pd.to_datetime(df['time'])

    fig, (ax1, ax2) = plt.subplots(2, 1, figsize=(10, 6), sharex=True)

    # Plot 1: Idle Minutes
    ax1.plot(df['time'], df['idle_seconds'] / 60.0, color='royalblue', label='Idle Time (mins)')
    ax1.axhline(y=15, color='red', linestyle='--', label='15-Min Slurm Harvest Threshold')
    ax1.set_ylabel('Idle Time (Minutes)')
    ax1.set_title('Lab Workstation Telemetry & Cycle-Harvesting Opportunity')
    ax1.legend(loc='upper left')
    ax1.grid(True, linestyle=':')

    # Plot 2: CPU Utilization
    ax2.plot(df['time'], df['cpu_percent'], color='darkorange', label='CPU Usage (%)')
    ax2.set_ylabel('CPU Load (%)')
    ax2.set_xlabel('Timestamp')
    ax2.set_ylim(0, 100)
    ax2.legend(loc='upper left')
    ax2.grid(True, linestyle=':')

    plt.tight_layout()
    plt.savefig('results/idle_telemetry_plot.png', dpi=300)
    print("Graph saved to results/idle_telemetry_plot.png")

if __name__ == "__main__":
    path = sys.argv[1] if len(sys.argv) > 1 else "test_idle.csv"
    plot_idle_log(path)